import React, { useState, useRef, useEffect } from 'react';
import { fileToBase64, generateTilePreview } from './services/geminiService';
import { TileSelector } from './components/TileSelector';
import { AppState, TileStyle } from './types';
import { 
  Upload, 
  ImageIcon, 
  Wand2, 
  Download, 
  RefreshCw, 
  Trash2,
  Layers,
  AlertCircle
} from './components/Icons';

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [prompt, setPrompt] = useState<string>('');
  const [selectedStyleId, setSelectedStyleId] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.startsWith('image/')) {
        setError('Please upload a valid image file (JPG, PNG).');
        return;
      }

      setAppState(AppState.UPLOADING);
      setError(null);

      try {
        const base64 = await fileToBase64(file);
        setOriginalImage(`data:${file.type};base64,${base64}`);
        setAppState(AppState.READY_TO_GENERATE);
        // Reset previous generation
        setGeneratedImage(null);
      } catch (err) {
        setError('Failed to process image. Please try again.');
        setAppState(AppState.IDLE);
      }
    }
  };

  const handleGenerate = async () => {
    if (!originalImage || !prompt) return;

    setAppState(AppState.GENERATING);
    setError(null);

    try {
      // Remove header from base64 string for the API call
      const base64Data = originalImage.split(',')[1];
      const mimeType = originalImage.split(';')[0].split(':')[1];

      const resultImage = await generateTilePreview(base64Data, prompt, mimeType);
      setGeneratedImage(resultImage);
      setAppState(AppState.COMPLETE);
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to generate preview. The image might be too complex or the service is busy.");
      setAppState(AppState.READY_TO_GENERATE);
    }
  };

  const handleReset = () => {
    setOriginalImage(null);
    setGeneratedImage(null);
    setPrompt('');
    setSelectedStyleId(null);
    setAppState(AppState.IDLE);
    setError(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleStyleSelect = (style: TileStyle) => {
    setSelectedStyleId(style.id);
    setPrompt(style.prompt);
  };

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      {/* Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-30">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-accent rounded-lg flex items-center justify-center text-white">
              <Layers className="w-5 h-5" />
            </div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">TileVision <span className="text-accent">AI</span></h1>
          </div>
          {appState !== AppState.IDLE && (
             <button 
               onClick={handleReset}
               className="text-sm font-medium text-slate-500 hover:text-red-500 transition-colors flex items-center gap-1"
             >
               <Trash2 className="w-4 h-4" /> Reset
             </button>
          )}
        </div>
      </header>

      <main className="flex-grow max-w-7xl mx-auto w-full px-4 sm:px-6 lg:px-8 py-8">

        {/* Error Notification */}
        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg flex items-center gap-3 animate-in fade-in slide-in-from-top-2">
            <AlertCircle className="w-5 h-5 shrink-0" />
            <p>{error}</p>
          </div>
        )}

        {appState === AppState.IDLE ? (
          // Empty State / Upload Hero
          <div className="max-w-xl mx-auto mt-12 text-center">
            <h2 className="text-3xl font-bold text-slate-900 mb-4">Reimagine your space</h2>
            <p className="text-slate-600 mb-8 text-lg">
              Upload a photo of your room and see how different tiles, floorings, and finishes look instantly using AI.
            </p>

            <div 
              onClick={() => fileInputRef.current?.click()}
              className="border-2 border-dashed border-slate-300 rounded-2xl bg-white p-12 cursor-pointer hover:border-accent hover:bg-blue-50 transition-all duration-300 group shadow-sm"
            >
              <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mx-auto mb-4 group-hover:bg-blue-100 transition-colors">
                <Upload className="w-8 h-8 text-slate-400 group-hover:text-accent" />
              </div>
              <p className="font-semibold text-slate-900">Click to upload photo</p>
              <p className="text-sm text-slate-500 mt-1">Supports JPG, PNG (Max 5MB)</p>
            </div>
            <input 
              type="file" 
              ref={fileInputRef} 
              className="hidden" 
              accept="image/png, image/jpeg, image/jpg"
              onChange={handleFileSelect}
            />
          </div>
        ) : (
          // Main Workspace
          <div className="grid lg:grid-cols-12 gap-8 h-full">

            {/* Left Sidebar: Controls */}
            <div className="lg:col-span-4 space-y-6 order-2 lg:order-1">

              <div className="bg-white p-5 rounded-xl shadow-sm border border-slate-200">
                <TileSelector selectedId={selectedStyleId} onSelect={handleStyleSelect} />

                <div className="mt-6 pt-6 border-t border-slate-100">
                  <label className="block text-sm font-semibold text-slate-700 mb-2">
                    Custom Prompt / Refinements
                  </label>
                  <textarea
                    value={prompt}
                    onChange={(e) => {
                      setPrompt(e.target.value);
                      setSelectedStyleId(null); // Clear preset selection if user edits manually
                    }}
                    placeholder="E.g., Change the floor to polished concrete and add a retro filter..."
                    className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-accent focus:border-transparent outline-none resize-none h-24"
                  />
                  <p className="text-xs text-slate-400 mt-2">
                    Tip: Be descriptive. Mention materials, colors, and lighting.
                  </p>
                </div>

                <div className="mt-6">
                  <button
                    onClick={handleGenerate}
                    disabled={appState === AppState.GENERATING || !prompt}
                    className={`
                      w-full py-3 px-4 rounded-lg flex items-center justify-center gap-2 font-semibold text-white transition-all
                      ${appState === AppState.GENERATING || !prompt 
                        ? 'bg-slate-300 cursor-not-allowed' 
                        : 'bg-accent hover:bg-blue-600 shadow-md hover:shadow-lg'}
                    `}
                  >
                    {appState === AppState.GENERATING ? (
                      <>
                        <RefreshCw className="w-5 h-5 animate-spin" />
                        Generating...
                      </>
                    ) : (
                      <>
                        <Wand2 className="w-5 h-5" />
                        Generate Preview
                      </>
                    )}
                  </button>
                </div>
              </div>

              {/* Tips Card */}
              <div className="bg-blue-50 p-5 rounded-xl border border-blue-100">
                <h4 className="text-blue-900 font-semibold mb-2 flex items-center gap-2">
                  <ImageIcon className="w-4 h-4" />
                  Best Practices
                </h4>
                <ul className="text-sm text-blue-800 space-y-2 list-disc list-inside">
                  <li>Use a clear, well-lit photo.</li>
                  <li>Ensure the floor is visible.</li>
                  <li>Try "Add a vintage filter" for style changes.</li>
                  <li>You can ask to remove objects like "remove the rug".</li>
                </ul>
              </div>

            </div>

            {/* Right Side: Preview */}
            <div className="lg:col-span-8 order-1 lg:order-2 flex flex-col gap-4">
              <div className="relative bg-slate-900 rounded-2xl overflow-hidden shadow-xl min-h-[400px] lg:h-[600px] group">

                {generatedImage ? (
                  // Generated View
                  <div className="relative w-full h-full">
                    <img 
                      src={generatedImage} 
                      alt="Generated Preview" 
                      className="w-full h-full object-contain bg-black"
                    />

                    {/* Toggle Button Overlay */}
                    <div className="absolute top-4 right-4 flex gap-2">
                      <a 
                        href={generatedImage} 
                        download="tile-preview.png"
                        className="bg-white/10 backdrop-blur-md hover:bg-white/20 text-white p-2 rounded-lg transition-colors"
                        title="Download Image"
                      >
                        <Download className="w-5 h-5" />
                      </a>
                    </div>

                    <div className="absolute bottom-4 left-4 bg-black/60 backdrop-blur-md text-white px-3 py-1.5 rounded-full text-xs font-medium border border-white/10">
                      Generated with Gemini 2.5
                    </div>
                  </div>
                ) : (
                  // Original / Loading View
                  <div className="w-full h-full relative">
                    {originalImage && (
                      <img 
                        src={originalImage} 
                        alt="Original" 
                        className={`w-full h-full object-contain bg-black transition-opacity duration-500 ${appState === AppState.GENERATING ? 'opacity-50' : 'opacity-100'}`}
                      />
                    )}

                    {/* Loading Overlay */}
                    {appState === AppState.GENERATING && (
                      <div className="absolute inset-0 flex flex-col items-center justify-center text-white z-10">
                        <div className="w-16 h-16 border-4 border-white/20 border-t-accent rounded-full animate-spin mb-4"></div>
                        <p className="text-lg font-medium animate-pulse">Designing your room...</p>
                        <p className="text-sm text-slate-300 mt-2">This may take a few seconds</p>
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Mini Gallery for switching between Original/Generated if both exist */}
              {generatedImage && (
                 <div className="flex gap-4 overflow-x-auto py-2">
                    <button 
                      onClick={() => setGeneratedImage(null)}
                      className="relative w-24 h-24 rounded-lg overflow-hidden border-2 border-slate-200 hover:border-accent transition-all shrink-0"
                    >
                      <img src={originalImage!} className="w-full h-full object-cover opacity-60 hover:opacity-100" />
                      <span className="absolute bottom-0 left-0 right-0 bg-black/50 text-white text-[10px] text-center py-1">Original</span>
                    </button>
                    <button 
                      className="relative w-24 h-24 rounded-lg overflow-hidden border-2 border-accent ring-2 ring-accent/20 shrink-0"
                    >
                      <img src={generatedImage} className="w-full h-full object-cover" />
                      <span className="absolute bottom-0 left-0 right-0 bg-accent text-white text-[10px] text-center py-1">Result</span>
                    </button>
                 </div>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export interface TileStyle {
  id: string;
  name: string;
  description: string;
  prompt: string;
  thumbnailColor: string;
}

export interface UserPreferences {
  roomType: string;
  designStyle: string;
  colorPalette: string[]; // e.g., ['Beige', 'Grey']
  tileSize: 'Small' | 'Medium' | 'Large';
  groutStyle: 'Seamless' | 'Standard' | 'Wide';
}

export interface CostConfig {
  areaSqFt: number;
  pricePerSqFt: number;
  wastagePercent: number;
}

export enum AppState {
  ONBOARDING = 'ONBOARDING',
  UPLOADING = 'UPLOADING',
  READY_TO_GENERATE = 'READY_TO_GENERATE',
  GENERATING = 'GENERATING',
  COMPLETE = 'COMPLETE',
}

import React, { useState, useRef, useEffect } from 'react';
import { ChevronRight, ChevronLeft } from 'lucide-react';

interface ComparisonSliderProps {
  beforeImage: string;
  afterImage: string;
}

export const ComparisonSlider: React.FC<ComparisonSliderProps> = ({ beforeImage, afterImage }) => {
  const [sliderPosition, setSliderPosition] = useState(50);
  const containerRef = useRef<HTMLDivElement>(null);
  const isDragging = useRef(false);

  const handleMove = (event: React.MouseEvent | React.TouchEvent) => {
    if (!isDragging.current || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = 'touches' in event ? event.touches[0].clientX : (event as React.MouseEvent).clientX;
    const position = ((x - rect.left) / rect.width) * 100;

    setSliderPosition(Math.min(Math.max(position, 0), 100));
  };

  return (
    <div 
      ref={containerRef}
      className="relative w-full h-full overflow-hidden rounded-2xl select-none cursor-col-resize group"
      onMouseDown={() => isDragging.current = true}
      onTouchStart={() => isDragging.current = true}
      onMouseUp={() => isDragging.current = false}
      onTouchEnd={() => isDragging.current = false}
      onMouseLeave={() => isDragging.current = false}
      onMouseMove={handleMove}
      onTouchMove={handleMove}
    >
      {/* Before Image (Background) */}
      <img 
        src={beforeImage} 
        alt="Original Room" 
        className="absolute inset-0 w-full h-full object-cover"
      />
      <div className="absolute top-4 left-4 bg-black/50 backdrop-blur-md text-white text-xs px-3 py-1 rounded-full pointer-events-none">
        Original
      </div>

      {/* After Image (Foreground - Clipped) */}
      <div 
        className="absolute inset-0 w-full h-full overflow-hidden"
        style={{ clipPath: `inset(0 ${100 - sliderPosition}% 0 0)` }}
      >
        <img 
          src={afterImage} 
          alt="New Design" 
          className="absolute inset-0 w-full h-full object-cover"
        />
        <div className="absolute top-4 right-4 bg-accent/90 backdrop-blur-md text-white text-xs px-3 py-1 rounded-full pointer-events-none shadow-sm">
          AI Design
        </div>
      </div>

      {/* Slider Handle */}
      <div 
        className="absolute inset-y-0 w-1 bg-white shadow-lg pointer-events-none"
        style={{ left: `${sliderPosition}%` }}
      >
        <div className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-8 h-8 bg-white rounded-full shadow-xl flex items-center justify-center text-stone-600">
           <div className="flex gap-0.5">
             <ChevronLeft className="w-3 h-3" />
             <ChevronRight className="w-3 h-3" />
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Calculator, DollarSign } from 'lucide-react';
import { CostConfig } from '../types';

export const CostEstimator: React.FC = () => {
  const [config, setConfig] = useState<CostConfig>({
    areaSqFt: 250,
    pricePerSqFt: 8.50,
    wastagePercent: 10
  });

  const totalCost = (config.areaSqFt * config.pricePerSqFt) * (1 + config.wastagePercent / 100);

  return (
    <div className="bg-surface-highlight border border-stone-200 rounded-2xl p-5 shadow-sm space-y-4">
      <div className="flex items-center gap-2 text-stone-800 font-semibold border-b border-stone-100 pb-2">
        <Calculator className="w-4 h-4 text-accent" />
        <h3>Live Cost Estimator</h3>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="text-xs font-medium text-stone-500 uppercase">Area (sq ft)</label>
          <input 
            type="number" 
            value={config.areaSqFt}
            onChange={(e) => setConfig({...config, areaSqFt: Number(e.target.value)})}
            className="w-full mt-1 px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm focus:ring-2 focus:ring-stone-200 outline-none"
          />
        </div>
        <div>
          <label className="text-xs font-medium text-stone-500 uppercase">Price / sq ft</label>
          <div className="relative">
            <DollarSign className="absolute left-2 top-2.5 w-3 h-3 text-stone-400" />
            <input 
              type="number" 
              value={config.pricePerSqFt}
              onChange={(e) => setConfig({...config, pricePerSqFt: Number(e.target.value)})}
              className="w-full mt-1 pl-7 pr-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm focus:ring-2 focus:ring-stone-200 outline-none"
            />
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between pt-2">
        <span className="text-xs text-stone-500">Incl. {config.wastagePercent}% wastage</span>
        <div className="text-right">
          <p className="text-xs text-stone-500 font-medium">Estimated Total</p>
          <p className="text-xl font-bold text-stone-900">${totalCost.toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { UserPreferences } from '../types';
import { ArrowRight, Check } from 'lucide-react';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const STEPS = [
  {
    id: 'room',
    title: "What room are we designing?",
    options: ["Living Room", "Bedroom", "Kitchen", "Bathroom", "Office", "Showroom"]
  },
  {
    id: 'style',
    title: "What is your preferred style?",
    options: ["Modern Minimalist", "Warm Luxury", "Rustic Traditional", "Industrial", "Scandinavian"]
  },
  {
    id: 'colors',
    title: "Select your color palette",
    options: ["Warm Beiges", "Cool Greys", "Crisp Whites", "Dark & Moody", "Earth Tones"]
  }
];

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [prefs, setPrefs] = useState<Partial<UserPreferences>>({
    tileSize: 'Large',
    groutStyle: 'Seamless'
  });

  const handleOptionSelect = (option: string) => {
    const currentStepId = STEPS[step].id;
    let newPrefs = { ...prefs };

    if (currentStepId === 'room') newPrefs.roomType = option;
    if (currentStepId === 'style') newPrefs.designStyle = option;
    if (currentStepId === 'colors') newPrefs.colorPalette = [option];

    setPrefs(newPrefs);

    if (step < STEPS.length - 1) {
      setStep(step + 1);
    } else {
      // Defaults for remaining fields
      onComplete(newPrefs as UserPreferences);
    }
  };

  const currentStep = STEPS[step];

  return (
    <div className="min-h-[60vh] flex flex-col items-center justify-center p-6 max-w-2xl mx-auto animate-fade-in">
      {/* Progress */}
      <div className="w-full flex gap-2 mb-8">
        {STEPS.map((_, idx) => (
          <div 
            key={idx} 
            className={`h-1 flex-1 rounded-full transition-all duration-500 ${idx <= step ? 'bg-accent' : 'bg-stone-200'}`} 
          />
        ))}
      </div>

      <h2 className="text-3xl font-light text-stone-900 mb-2 text-center">{currentStep.title}</h2>
      <p className="text-stone-500 mb-8 text-center">Step {step + 1} of {STEPS.length}</p>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 w-full">
        {currentStep.options.map((option) => (
          <button
            key={option}
            onClick={() => handleOptionSelect(option)}
            className="group relative p-6 bg-surface-highlight border border-stone-200 rounded-2xl hover:border-accent hover:shadow-lg hover:-translate-y-1 transition-all duration-300 text-left"
          >
            <span className="font-medium text-stone-700 group-hover:text-stone-900">{option}</span>
            <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity text-accent">
              <ArrowRight className="w-4 h-4" />
            </div>
          </button>
        ))}
      </div>

      {step > 0 && (
          <button 
            onClick={() => setStep(step - 1)}
            className="mt-8 text-stone-400 hover:text-stone-600 text-sm font-medium"
          >
            Go Back
          </button>
      )}
    </div>
  );
};

