import { GoogleGenAI } from "@google/genai";

// Initialize the Gemini AI client
// The API key is guaranteed to be in process.env.API_KEY per system instructions
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

/**
 * Converts a File object to a Base64 string, resizing it to max 1024px and converting to JPEG.
 * This prevents 'Rpc failed due to xhr error' caused by large payloads.
 */
export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = (event) => {
      const img = new Image();
      img.src = event.target?.result as string;
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 1024;

        if (width > MAX_SIZE || height > MAX_SIZE) {
          if (width > height) {
            height = Math.round((height * MAX_SIZE) / width);
            width = MAX_SIZE;
          } else {
            width = Math.round((width * MAX_SIZE) / height);
            height = MAX_SIZE;
          }
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
            reject(new Error("Could not get canvas context"));
            return;
        }
        ctx.drawImage(img, 0, 0, width, height);

        // Convert to JPEG with 0.8 quality for optimal API payload size
        const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
        resolve(dataUrl.split(',')[1]);
      };
      img.onerror = (err) => reject(err);
    };
    reader.onerror = (err) => reject(err);
  });
};

/**
 * Estimates the visible floor area in square feet using Gemini 2.5 Flash (text model).
 */
export const estimateFloorArea = async (imageBase64: string): Promise<number> => {
    try {
        const model = 'gemini-2.5-flash';
        const response = await ai.models.generateContent({
            model: model,
            contents: {
                parts: [
                    {
                        inlineData: {
                            data: imageBase64,
                            mimeType: 'image/jpeg',
                        },
                    },
                    {
                        text: "Analyze this room image. Estimate the approximate square footage of the VISIBLE floor area. Return ONLY a single number (e.g., 150). Do not return text or ranges. If unsure, guess 250.",
                    },
                ],
            },
        });

        const text = response.text || "250";
        const number = parseInt(text.replace(/[^0-9]/g, ''), 10);
        return isNaN(number) ? 250 : number;
    } catch (error) {
        console.warn("Failed to estimate floor area, defaulting to 250", error);
        return 250;
    }
};

/**
 * Generates a new version of the image based on the prompt using Gemini 2.5 Flash Image.
 */
export const generateTilePreview = async (
  imageBase64: string,
  prompt: string,
  mimeType: string = 'image/jpeg'
): Promise<string> => {
  try {
    // Using gemini-2.5-flash-image as requested for image editing/generation
    const model = 'gemini-2.5-flash-image';

    const response = await ai.models.generateContent({
      model: model,
      contents: {
        parts: [
          {
            inlineData: {
              data: imageBase64,
              mimeType: mimeType,
            },
          },
          {
            text: `Edit this image strictly following these instructions: ${prompt}. Maintain the original perspective, lighting, and structural elements of the room exactly. High realism, 8k resolution.`,
          },
        ],
      },
    });

    // Extract the image from the response
    // The response might contain text or inlineData. We scan for inlineData.
    if (response.candidates && response.candidates.length > 0) {
      const parts = response.candidates[0].content.parts;
      for (const part of parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:${part.inlineData.mimeType || 'image/png'};base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image data found in the response.");

  } catch (error) {
    console.error("Gemini Generation Error:", error);
    throw error;
  }
};

import React, { useState } from 'react';
import { UserPreferences } from '../types';
import { ArrowRight } from 'lucide-react';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const STEPS = [
  {
    id: 'room',
    title: "What room are we designing?",
    options: ["Living Room", "Bedroom", "Kitchen", "Bathroom", "Office", "Showroom"]
  },
  {
    id: 'style',
    title: "What is your preferred style?",
    options: ["Modern Minimalist", "Warm Luxury", "Rustic Traditional", "Industrial", "Scandinavian"]
  },
  {
    id: 'colors',
    title: "Select your color palette",
    options: [] as string[] // Dynamic
  }
];

const STYLE_COLOR_MAP: Record<string, string[]> = {
  "Modern Minimalist": ["Cool Greys", "Crisp Whites", "Matte Black", "Neutral Beige", "Monochrome"],
  "Warm Luxury": ["Warm Beiges", "Gold Accents", "Cream", "Rich Walnut", "Champagne"],
  "Rustic Traditional": ["Earth Tones", "Terracotta", "Warm Oak", "Slate Grey", "Olive"],
  "Industrial": ["Concrete Grey", "Charcoal", "Raw Steel", "Brick Red", "Aged Wood"],
  "Scandinavian": ["Light Ash", "Soft White", "Pale Blue", "Muted Sage", "Blush Pink"]
};

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [prefs, setPrefs] = useState<Partial<UserPreferences>>({
    tileSize: 'Large',
    groutStyle: 'Seamless',
    finish: 'Matte'
  });

  const handleOptionSelect = (option: string) => {
    const currentStepId = STEPS[step].id;
    let newPrefs = { ...prefs };

    if (currentStepId === 'room') newPrefs.roomType = option;
    if (currentStepId === 'style') newPrefs.designStyle = option;
    if (currentStepId === 'colors') newPrefs.colorPalette = [option];

    setPrefs(newPrefs);

    if (step < STEPS.length - 1) {
      setStep(step + 1);
    } else {
      // Defaults for remaining fields
      onComplete(newPrefs as UserPreferences);
    }
  };

  // Dynamically get options
  const currentStepDef = STEPS[step];
  let currentOptions = currentStepDef.options;

  if (currentStepDef.id === 'colors' && prefs.designStyle) {
    currentOptions = STYLE_COLOR_MAP[prefs.designStyle] || ["Beige", "Grey", "White", "Black"];
  }

  return (
    <div className="min-h-[60vh] flex flex-col items-center justify-center p-6 max-w-2xl mx-auto animate-fade-in">
      {/* Progress */}
      <div className="w-full flex gap-2 mb-8">
        {STEPS.map((_, idx) => (
          <div 
            key={idx} 
            className={`h-1 flex-1 rounded-full transition-all duration-500 ${idx <= step ? 'bg-accent' : 'bg-stone-200'}`} 
          />
        ))}
      </div>

      <h2 className="text-3xl font-light text-stone-900 mb-2 text-center">{currentStepDef.title}</h2>
      <p className="text-stone-500 mb-8 text-center">Step {step + 1} of {STEPS.length}</p>

      <div className="grid grid-cols-2 md:grid-cols-3 gap-4 w-full">
        {currentOptions.map((option) => (
          <button
            key={option}
            onClick={() => handleOptionSelect(option)}
            className="group relative p-6 bg-surface-highlight border border-stone-200 rounded-2xl hover:border-accent hover:shadow-lg hover:-translate-y-1 transition-all duration-300 text-left"
          >
            <span className="font-medium text-stone-700 group-hover:text-stone-900">{option}</span>
            <div className="absolute bottom-4 right-4 opacity-0 group-hover:opacity-100 transition-opacity text-accent">
              <ArrowRight className="w-4 h-4" />
            </div>
          </button>
        ))}
      </div>

      {step > 0 && (
          <button 
            onClick={() => setStep(step - 1)}
            className="mt-8 text-stone-400 hover:text-stone-600 text-sm font-medium"
          >
            Go Back
          </button>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
