        <div>
          <label className="text-xs font-medium text-stone-500 uppercase">Area (sq ft)</label>
          <input 
            type="number" 
            value={config.areaSqFt}
            onChange={(e) => setConfig({...config, areaSqFt: Number(e.target.value)})}
            className="w-full mt-1 px-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm focus:ring-2 focus:ring-stone-200 outline-none"
          />
        </div>
        <div>
          <label className="text-xs font-medium text-stone-500 uppercase">Price / sq ft</label>
          <div className="relative">
            <DollarSign className="absolute left-2 top-2.5 w-3 h-3 text-stone-400" />
            <input 
              type="number" 
              value={config.pricePerSqFt}
              onChange={(e) => setConfig({...config, pricePerSqFt: Number(e.target.value)})}
              className="w-full mt-1 pl-7 pr-3 py-2 bg-stone-50 border border-stone-200 rounded-lg text-sm focus:ring-2 focus:ring-stone-200 outline-none"
            />
