        </div>
      </div>

      <div className="flex items-center justify-between pt-2">
        <span className="text-xs text-stone-500">Incl. {config.wastagePercent}% wastage</span>
        <div className="text-right">
          <p className="text-xs text-stone-500 font-medium">Estimated Total</p>
          <p className="text-xl font-bold text-stone-900">${totalCost.toLocaleString(undefined, { maximumFractionDigits: 0 })}</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { fileToBase64, generateTilePreview, estimateFloorArea } from './services/geminiService';
import { Onboarding } from './components/Onboarding';
import { ComparisonSlider } from './components/ComparisonSlider';
import { CostEstimator } from './components/CostEstimator';
import { AppState, UserPreferences } from './types';
import { 
  Upload, 
  Wand2, 
  Download, 
  RefreshCw, 
  Trash2,
  CheckCircle2,
  Scan,
  Lightbulb,
  Maximize2
} from 'lucide-react';

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.ONBOARDING);
  const [userPrefs, setUserPrefs] = useState<UserPreferences | null>(null);

  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Quick settings in visualizer
  const [activeColor, setActiveColor] = useState<string>('');
  const [aiEstimatedArea, setAiEstimatedArea] = useState<number | undefined>(undefined);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setUserPrefs(prefs);
    setActiveColor(prefs.colorPalette[0]);
    setAppState(AppState.IDLE); // Actually, we'll map IDLE to UPLOADING UI in render
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.startsWith('image/')) {
        setError('Please upload a valid image file (JPG, PNG).');
        return;
      }

      setAppState(AppState.UPLOADING);
      setError(null);
      setGeneratedImage(null); // Clear previous generation

      try {
        const base64 = await fileToBase64(file);
        // Important: Service standardizes to JPEG to prevent API payload errors
        const mimeType = 'image/jpeg';
        const fullDataUrl = `data:${mimeType};base64,${base64}`;

        setOriginalImage(fullDataUrl);
        setAppState(AppState.READY_TO_GENERATE);

        // Silent AI approximation of floor area
        // Send the raw base64 (without data prefix) to the service
        estimateFloorArea(base64).then(area => {
          setAiEstimatedArea(area);
        });

      } catch (err) {
        console.error("File processing error", err);
        setError('Failed to process image. Please try again.');
        setAppState(AppState.IDLE); // Fallback
      }
    }
  };

  const generateWithPrefs = async (img: string, prefs: UserPreferences, colorOverride: string) => {
    if (!img || !prefs) return;
    setAppState(AppState.GENERATING);
    setError(null);

    // Dynamic Prompt Construction
    const prompt = `
      Replace the flooring in this ${prefs.roomType} with high-end ${colorOverride} flooring.
      Style: ${prefs.designStyle}.
      Finish: ${prefs.finish || 'Matte'}.
      Texture: Photorealistic, believable material suitable for interiors with a ${prefs.finish} look.
      Details: ${prefs.tileSize} tiles with ${prefs.groutStyle} grout.
      Maintain exact lighting, shadows, and perspective of the original room.
      Keep furniture and walls unchanged. High trust, architectural visualization quality.
    `;

    try {
      const base64Data = img.split(',')[1];
      const mimeType = img.split(';')[0].split(':')[1];
      const resultImage = await generateTilePreview(base64Data, prompt.trim(), mimeType);

      setGeneratedImage(resultImage);
      setAppState(AppState.COMPLETE);
    } catch (err: any) {
      console.error(err);
      let errorMessage = "AI is busy refining your design. Please try again.";
      // Handle payload/network errors more specifically
      if (err.message && (err.message.includes("500") || err.message.includes("XHR") || err.message.includes("Rpc"))) {
          errorMessage = "Network error: The image might be too complex or the server is busy. Please try again.";
      }
      setError(errorMessage);
      setAppState(AppState.READY_TO_GENERATE);
    }
  };

  const handleColorSwitch = (color: string) => {
    setActiveColor(color);
    if (originalImage && userPrefs && generatedImage) {
      // Only auto-regenerate if an image has already been generated once.
      // Otherwise, just update the state so the user can click "Generate"
      generateWithPrefs(originalImage, userPrefs, color);
    }
  };

  const handleReset = () => {
    setOriginalImage(null);
    setGeneratedImage(null);
    setAppState(AppState.ONBOARDING);
    setUserPrefs(null);
    setAiEstimatedArea(undefined);
  };

  // -- Render Logic --

  if (appState === AppState.ONBOARDING) {
    return (
      <div className="min-h-screen bg-stone-50 flex items-center justify-center">
        <Onboarding onComplete={handleOnboardingComplete} />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-stone-50 flex flex-col font-sans">
      {/* Navbar */}
      <nav className="bg-surface-highlight border-b border-stone-200 sticky top-0 z-40 backdrop-blur-sm bg-white/80">
        <div className="max-w-7xl mx-auto px-6 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-stone-900 rounded-lg flex items-center justify-center text-white">
              <Scan className="w-5 h-5" />
            </div>
            <span className="font-semibold text-stone-900 tracking-tight">TileVision</span>
          </div>
          <button onClick={handleReset} className="text-sm text-stone-500 hover:text-red-500 transition-colors flex items-center gap-1.5">
            <Trash2 className="w-4 h-4" /> Start Over
          </button>
        </div>
      </nav>

      <main className="flex-grow p-4 md:p-6 lg:p-8 max-w-7xl mx-auto w-full">

        {/* Error Toast */}
        {error && (
          <div className="fixed top-20 right-6 bg-red-50 text-red-800 px-4 py-3 rounded-xl border border-red-100 shadow-lg animate-fade-in flex items-center gap-3 z-50">
            <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse" />
            {error}
          </div>
        )}

        {!originalImage ? (
          // Upload Area
          <div className="max-w-xl mx-auto mt-12 animate-slide-up">
