import React, { useState, useEffect } from 'react';
import { Calculator } from 'lucide-react';
import { CostConfig } from '../types';

interface CostEstimatorProps {
  estimatedArea?: number;
}

export const CostEstimator: React.FC<CostEstimatorProps> = ({ estimatedArea }) => {
  const [config, setConfig] = useState<CostConfig>({
    areaSqFt: 250,
    pricePerSqFt: 145, // Updated default for INR
    wastagePercent: 10
  });

  // Update config when AI estimation comes in
  useEffect(() => {
    if (estimatedArea) {
      setConfig(prev => ({ ...prev, areaSqFt: estimatedArea }));
    }
  }, [estimatedArea]);

  const totalCost = (config.areaSqFt * config.pricePerSqFt) * (1 + config.wastagePercent / 100);

  // Formatter for Indian Rupee
  const formatRupee = (amount: number) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0
    }).format(amount);
  };

  return (
    <div className="bg-white border border-stone-200 rounded-xl p-6 shadow-sm space-y-6">
      <div className="flex items-center gap-3 text-stone-800 border-b border-stone-100 pb-4">
        <div className="p-2 bg-stone-50 rounded-lg">
           <Calculator className="w-4 h-4 text-stone-600" />
        </div>
        <h3 className="font-serif text-lg tracking-tight">Cost Estimation</h3>
      </div>

      <div className="space-y-4">
        <div className="flex justify-between items-center group">
          <label className="text-xs font-semibold text-stone-400 uppercase tracking-wider">Area (sq ft)</label>
          <input 
            type="number" 
            value={config.areaSqFt}
            onChange={(e) => setConfig({...config, areaSqFt: Number(e.target.value)})}
            className="w-24 text-right bg-transparent border-b border-stone-200 focus:border-stone-800 outline-none font-medium text-stone-800 transition-colors"
          />
        </div>

        <div className="flex justify-between items-center group">
            <label className="text-xs font-semibold text-stone-400 uppercase tracking-wider">Price / sq ft</label>
            <div className="flex items-center justify-end w-28 border-b border-stone-200 focus-within:border-stone-800 transition-colors">
                <span className="text-stone-400 mr-1">₹</span>
                <input 
                type="number" 
                value={config.pricePerSqFt}
                onChange={(e) => setConfig({...config, pricePerSqFt: Number(e.target.value)})}
                className="w-full text-right bg-transparent outline-none font-medium text-stone-800"
                />
            </div>
        </div>
      </div>

      <div className="pt-4 mt-2 border-t border-stone-50 flex items-end justify-between">
        <div className="flex flex-col">
            <span className="text-[10px] font-bold text-stone-400 uppercase tracking-widest mb-1">Estimated Total</span>
            <span className="text-xs text-stone-400">Incl. {config.wastagePercent}% wastage</span>
        </div>
        <span className="font-serif text-3xl text-stone-900">{formatRupee(totalCost)}</span>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { UserPreferences } from '../types';
import { ArrowRight, Sparkles } from 'lucide-react';

interface OnboardingProps {
  onComplete: (prefs: UserPreferences) => void;
}

const STEPS = [
  {
    id: 'room',
    title: "The Space",
    subtitle: "What type of room are we transforming?",
    options: ["Living Room", "Master Bedroom", "Gourmet Kitchen", "Spa Bathroom", "Home Office", "Showroom"]
  },
  {
    id: 'style',
    title: "The Aesthetic",
    subtitle: "Define the mood of your new interior.",
    options: ["Modern Minimalist", "Warm Luxury", "Rustic Traditional", "Industrial Chic", "Scandinavian"]
  },
  {
    id: 'colors',
    title: "The Palette",
    subtitle: "Select the primary tone for your flooring.",
    options: [] as string[] // Dynamic
  }
];

const STYLE_COLOR_MAP: Record<string, string[]> = {
  "Modern Minimalist": [
    "Cool Grey", "Arctic White", "Matte Black", "Taupe", "Slate",
    "Charcoal", "Silver", "Dove Grey", "Midnight Blue", "Cement"
  ],
  "Warm Luxury": [
    "Warm Beige", "Crema Marfil", "Rich Walnut", "Champagne", "Honey Oak",
    "Gold Vein", "Ivory", "Espresso", "Travertine", "Mocha"
  ],
  "Rustic Traditional": [
    "Terracotta", "Natural Stone", "Warm Oak", "Antique Grey", "Olive",
    "Sandstone", "Brick Red", "Mahogany", "Forest Green", "Amber"
  ],
  "Industrial Chic": [
    "Polished Concrete", "Charcoal", "Raw Steel", "Brick Red", "Weathered Wood",
    "Rust", "Gunmetal", "Aged Bronze", "Iron", "Distressed Leather"
  ],
  "Scandinavian": [
    "Light Ash", "Pale Birch", "Soft White", "Muted Sage", "Blush",
    "Mint", "Cloud Blue", "Peach", "Frost", "Light Pine"
  ]
};

export const Onboarding: React.FC<OnboardingProps> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const [prefs, setPrefs] = useState<Partial<UserPreferences>>({
    groutStyle: 'Seamless',
    finish: 'Matte'
  });

  const handleOptionSelect = (option: string) => {
    const currentStepId = STEPS[step].id;
    let newPrefs = { ...prefs };

    if (currentStepId === 'room') newPrefs.roomType = option;
    if (currentStepId === 'style') newPrefs.designStyle = option;
    if (currentStepId === 'colors') newPrefs.colorPalette = [option];

    setPrefs(newPrefs);

    if (step < STEPS.length - 1) {
      setStep(step + 1);
    } else {
      onComplete(newPrefs as UserPreferences);
    }
  };

  // Dynamically get options
  const currentStepDef = STEPS[step];
  let currentOptions = currentStepDef.options;

  if (currentStepDef.id === 'colors' && prefs.designStyle) {
    currentOptions = STYLE_COLOR_MAP[prefs.designStyle] || ["Beige", "Grey", "White", "Black"];
  }

  return (
    <div className="relative w-full max-w-4xl mx-auto px-6 py-12 animate-fade-in">
      <div className="absolute top-0 left-1/2 -translate-x-1/2 -translate-y-12 opacity-50">
        <Sparkles className="w-12 h-12 text-stone-200" />
      </div>

      <div className="text-center mb-16 space-y-3">
         <span className="text-xs font-bold tracking-[0.2em] text-stone-400 uppercase">Step {step + 1} of {STEPS.length}</span>
         <h2 className="text-5xl font-serif text-stone-900 leading-tight">{currentStepDef.title}</h2>
         <p className="text-xl text-stone-500 font-light">{currentStepDef.subtitle}</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 w-full">
        {currentOptions.map((option, idx) => (
          <button
            key={option}
            onClick={() => handleOptionSelect(option)}
            className="group relative p-8 bg-white border border-stone-100 shadow-sm hover:shadow-xl rounded-xl transition-all duration-500 text-left hover:-translate-y-1 overflow-hidden"
            style={{ animationDelay: `${idx * 50}ms` }}
          >
            <div className="absolute inset-0 bg-gradient-to-br from-white to-stone-50 opacity-0 group-hover:opacity-100 transition-opacity" />
            <div className="relative z-10 flex justify-between items-center">
                <span className="font-serif text-2xl text-stone-700 group-hover:text-stone-900 group-hover:italic transition-colors">{option}</span>
                <ArrowRight className="w-5 h-5 text-stone-300 group-hover:text-accent transform group-hover:translate-x-1 transition-all" />
            </div>
          </button>
        ))}
      </div>

      <div className="mt-12 flex justify-center">
        {step > 0 && (
            <button 
                onClick={() => setStep(step - 1)}
                className="text-stone-400 hover:text-stone-600 text-sm font-medium tracking-wide uppercase transition-colors"
            >
                Back to previous step
            </button>
        )}
      </div>

      {/* Progress Dots */}
      <div className="fixed bottom-10 left-0 right-0 flex justify-center gap-3">
        {STEPS.map((_, idx) => (
          <div 
            key={idx} 
            className={`w-2 h-2 rounded-full transition-all duration-500 ${idx === step ? 'bg-stone-800 scale-125' : 'bg-stone-300'}`} 
          />
        ))}
      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { fileToBase64, generateTilePreview, estimateFloorArea } from './services/geminiService';
import { Onboarding } from './components/Onboarding';
import { ComparisonSlider } from './components/ComparisonSlider';
import { CostEstimator } from './components/CostEstimator';
import { AppState, UserPreferences } from './types';
import { 
  Upload, 
  Wand2, 
  Download, 
  RefreshCw, 
  Trash2,
  CheckCircle2,
  Scan,
  Maximize2,
  ArrowRight
} from 'lucide-react';

// Helper to map fancy color names to hex codes for UI previews
const getColorHex = (name: string) => {
  const map: Record<string, string> = {
    'Cool Grey': '#9ca3af', 'Arctic White': '#f9fafb', 'Matte Black': '#171717', 'Taupe': '#b0a696', 'Slate': '#64748b',
    'Charcoal': '#374151', 'Silver': '#e5e7eb', 'Dove Grey': '#d1d5db', 'Midnight Blue': '#1e3a8a', 'Cement': '#9ca3af',
    'Warm Beige': '#e8dec8', 'Crema Marfil': '#f5f5dc', 'Rich Walnut': '#5d4037', 'Champagne': '#fad6a5', 'Honey Oak': '#d4a017',
    'Gold Vein': '#ffd700', 'Ivory': '#fffff0', 'Espresso': '#4e342e', 'Travertine': '#eecfa1', 'Mocha': '#a0522d',
    'Terracotta': '#e2725b', 'Natural Stone': '#8b8589', 'Warm Oak': '#cd853f', 'Antique Grey': '#78716c', 'Olive': '#808000',
    'Sandstone': '#d2b48c', 'Brick Red': '#cb4154', 'Mahogany': '#c04000', 'Forest Green': '#228b22', 'Amber': '#ffbf00',
    'Polished Concrete': '#b0c4de', 'Raw Steel': '#71797e', 'Weathered Wood': '#deb887',
    'Rust': '#b7410e', 'Gunmetal': '#2a3439', 'Aged Bronze': '#cd7f32', 'Iron': '#434b4d', 'Distressed Leather': '#8b4513',
    'Light Ash': '#f5f5f5', 'Pale Birch': '#f6ead1', 'Soft White': '#f8f8ff', 'Muted Sage': '#9caf88', 'Blush': '#ffb6c1',
    'Mint': '#98ff98', 'Cloud Blue': '#b0e0e6', 'Peach': '#ffdab9', 'Frost': '#e0ffff', 'Light Pine': '#fbf8e6',
    'Beige': '#f5f5dc', 'Grey': '#808080', 'White': '#ffffff', 'Black': '#000000'
  };
  return map[name] || name.toLowerCase();
};

export default function App() {
  const [appState, setAppState] = useState<AppState>(AppState.ONBOARDING);
  const [userPrefs, setUserPrefs] = useState<UserPreferences | null>(null);

  const [originalImage, setOriginalImage] = useState<string | null>(null);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Quick settings in visualizer
  const [activeColor, setActiveColor] = useState<string>('');
  const [aiEstimatedArea, setAiEstimatedArea] = useState<number | undefined>(undefined);

  const handleOnboardingComplete = (prefs: UserPreferences) => {
    setUserPrefs(prefs);
    setActiveColor(prefs.colorPalette[0]);
    setAppState(AppState.IDLE); 
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      if (!file.type.startsWith('image/')) {
        setError('Please upload a valid image file (JPG, PNG).');
        return;
      }

      setAppState(AppState.UPLOADING);
      setError(null);
      setGeneratedImage(null); // Clear previous generation

      try {
        const base64 = await fileToBase64(file);
        const mimeType = 'image/jpeg';
        const fullDataUrl = `data:${mimeType};base64,${base64}`;

        setOriginalImage(fullDataUrl);
        setAppState(AppState.READY_TO_GENERATE);

        estimateFloorArea(base64).then(area => {
          setAiEstimatedArea(area);
        });

      } catch (err) {
        console.error("File processing error", err);
        setError('Failed to process image. Please try again.');
        setAppState(AppState.IDLE); // Fallback
      }
    }
  };

  const generateWithPrefs = async (img: string, prefs: UserPreferences, colorOverride: string) => {
    if (!img || !prefs) return;
    setAppState(AppState.GENERATING);
    setError(null);

    // Prompt updated to remove tile size
    const prompt = `
      Replace the flooring in this ${prefs.roomType} with high-end ${colorOverride} flooring.
      Style: ${prefs.designStyle}.
      Finish: ${prefs.finish || 'Matte'}.
      Texture: Photorealistic, believable material suitable for interiors with a ${prefs.finish} look.
      Details: ${prefs.groutStyle} grout lines where appropriate.
      Maintain exact lighting, shadows, and perspective of the original room.
      Keep furniture and walls unchanged. High trust, architectural visualization quality.
    `;

    try {
      const base64Data = img.split(',')[1];
      const mimeType = img.split(';')[0].split(':')[1];
      const resultImage = await generateTilePreview(base64Data, prompt.trim(), mimeType);

      setGeneratedImage(resultImage);
      setAppState(AppState.COMPLETE);
    } catch (err: any) {
      console.error(err);
      let errorMessage = "AI is busy refining your design. Please try again.";
      if (err.message && (err.message.includes("500") || err.message.includes("XHR") || err.message.includes("Rpc"))) {
          errorMessage = "Network error: The image might be too complex or the server is busy. Please try again.";
      }
      setError(errorMessage);
      setAppState(AppState.READY_TO_GENERATE);
    }
  };

  const handleColorSwitch = (color: string) => {
    setActiveColor(color);
    if (originalImage && userPrefs && generatedImage) {
      generateWithPrefs(originalImage, userPrefs, color);
    }
  };

  const handleReset = () => {
    setOriginalImage(null);
    setGeneratedImage(null);
    setAppState(AppState.ONBOARDING);
    setUserPrefs(null);
    setAiEstimatedArea(undefined);
  };

  // -- Render Logic --

  if (appState === AppState.ONBOARDING) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-stone-50 via-stone-100 to-stone-200 flex items-center justify-center">
        <Onboarding onComplete={handleOnboardingComplete} />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-stone-50 via-stone-50 to-stone-100 flex flex-col font-sans text-stone-900">
      {/* Premium Navbar */}
      <nav className="sticky top-0 z-50 backdrop-blur-md bg-white/70 border-b border-stone-200/60 support-backdrop-blur:bg-white/60">
        <div className="max-w-[1600px] mx-auto px-8 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-stone-900 flex items-center justify-center text-white rounded-none shadow-lg">
              <Scan className="w-5 h-5" />
            </div>
            <span className="font-serif text-2xl font-medium text-stone-900 tracking-tight">TileVision</span>
          </div>
          <button onClick={handleReset} className="text-xs uppercase tracking-widest font-semibold text-stone-500 hover:text-stone-900 transition-colors flex items-center gap-2">
            New Project
          </button>
        </div>
      </nav>

      <main className="flex-grow p-4 md:p-8 max-w-[1600px] mx-auto w-full">

        {/* Error Toast */}
        {error && (
          <div className="fixed top-24 right-8 bg-white text-red-900 px-6 py-4 rounded-lg border border-red-100 shadow-xl animate-fade-in flex items-center gap-3 z-50">
            <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse" />
            <span className="font-medium">{error}</span>
          </div>
        )}

        {!originalImage ? (
          // Premium Upload Area
          <div className="max-w-2xl mx-auto mt-20 animate-slide-up text-center">
             <div className="mb-12 space-y-4">
               <h1 className="text-5xl md:text-6xl font-serif text-stone-900 leading-tight">
                 Visualize your <span className="italic text-stone-500">{userPrefs?.roomType.toLowerCase()}</span><br/> in {userPrefs?.designStyle} style.
               </h1>
               <p className="text-lg text-stone-500 font-light max-w-lg mx-auto leading-relaxed">
                 Upload a photo to instantly preview premium flooring options tailored to your taste.
               </p>
             </div>

             <div 
               onClick={() => fileInputRef.current?.click()}
               className="relative overflow-hidden bg-white/50 backdrop-blur-sm border border-stone-200 rounded-2xl p-20 flex flex-col items-center justify-center cursor-pointer hover:border-stone-400 hover:bg-white hover:shadow-2xl transition-all duration-500 group"
             >
               <div className="absolute inset-0 bg-gradient-to-tr from-stone-50 to-white opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
               <div className="relative z-10">
                 <div className="w-24 h-24 bg-white border border-stone-100 rounded-full flex items-center justify-center mb-8 group-hover:scale-110 transition-transform duration-500 text-stone-400 group-hover:text-stone-900 shadow-md">
                   <Upload className="w-8 h-8" />
                 </div>
                 <span className="font-serif text-2xl text-stone-900 block mb-2">Upload Room Photo</span>
                 <span className="text-stone-400 text-sm uppercase tracking-wider">High Resolution JPG or PNG</span>
               </div>
             </div>
             <input type="file" ref={fileInputRef} className="hidden" accept="image/*" onChange={handleFileSelect} />
          </div>
        ) : (
          // Main Workspace
          <div className="grid lg:grid-cols-12 gap-8 h-[calc(100vh-140px)]">

            {/* Left Panel: Controls */}
            <div className="lg:col-span-3 space-y-6 overflow-y-auto pr-4 custom-scrollbar">

              <div className="flex items-center gap-3 mb-6">
                <div className="h-px bg-stone-200 flex-1" />
                <span className="text-[10px] uppercase tracking-[0.2em] text-stone-400 font-bold">Configuration</span>
                <div className="h-px bg-stone-200 flex-1" />
              </div>

              {/* Verified Badge */}
              {aiEstimatedArea && (
                  <div className="bg-white/60 border border-stone-200 p-3 rounded-lg flex items-center gap-3 shadow-sm">
                    <Scan className="w-4 h-4 text-stone-500" />
                    <span className="text-xs font-medium text-stone-600 uppercase tracking-wide">AI Scale: {aiEstimatedArea} sq ft</span>
                  </div>
               )}

              {/* Material Selection */}
              <div className="space-y-4">
