                 )}

                 {/* Generate Button Overlay */}
                 {!generatedImage && appState !== AppState.GENERATING && (
                    <div className="absolute inset-0 z-20 flex flex-col items-center justify-center bg-stone-900/5 backdrop-blur-[1px]">
