              {/* Material Selection */}
              <div className="space-y-4">
                <h3 className="font-serif text-lg text-stone-900">Material Selection</h3>
                <div className="grid grid-cols-1 gap-3">
                   {[...new Set([...(userPrefs?.colorPalette || []), 'Beige', 'Grey', 'White', 'Charcoal', 'Oak'])].slice(0, 8).map((color) => (
                     <button
                       key={color}
                       onClick={() => handleColorSwitch(color)}
                       disabled={appState === AppState.GENERATING}
