  const generateWithPrefs = async (img: string, prefs: UserPreferences, colorOverride: string) => {
    if (!img || !prefs) return;
    setAppState(AppState.GENERATING);
    setError(null);

    const prompt = `
      Replace the flooring in this ${prefs.roomType} with high-end ${colorOverride} flooring.
      Style: ${prefs.designStyle}.
      Finish: ${prefs.finish || 'Matte'}.
      Texture: Photorealistic, believable material suitable for interiors with a ${prefs.finish} look.
      Details: ${prefs.groutStyle} grout lines where appropriate.
      Maintain exact lighting, shadows, and perspective of the original room.
      Keep furniture and walls unchanged. High trust, architectural visualization quality.
    `;

    try {
      const base64Data = img.split(',')[1];
      const mimeType = img.split(';')[0].split(':')[1];
      const resultImage = await generateTilePreview(base64Data, prompt.trim(), mimeType);

      setGeneratedImage(resultImage);
      setAppState(AppState.COMPLETE);
    } catch (err: any) {
      console.error(err);
      let errorMessage = "AI is busy refining your design. Please try again.";
      if (err.message && (err.message.includes("403") || err.message.includes("PERMISSION_DENIED"))) {
         errorMessage = "Access Denied: Please ensure your API Key is connected and billing is enabled for the Gemini Pro Vision model.";
      } else if (err.message && (err.message.includes("500") || err.message.includes("XHR") || err.message.includes("Rpc"))) {
          errorMessage = "Network error: The image might be too complex or the server is busy. Please try again.";
      }
      setError(errorMessage);
      setAppState(AppState.READY_TO_GENERATE);
    }
  };

  const handleColorSwitch = (color: string) => {
    setActiveColor(color);
