  "Modern Minimalist": [
    "Cool Grey", "Arctic White", "Matte Black", "Taupe", "Slate",
    "Charcoal", "Silver", "Dove Grey", "Midnight Blue", "Cement"
  ],
  "Warm Luxury": [
    "Warm Beige", "Crema Marfil", "Rich Walnut", "Champagne", "Honey Oak",
