// 1. Define the Style Map to determine "Recommended" colors
const STYLE_COLOR_MAP: Record<string, string[]> = {
  "Modern Minimalist": [
    "Cool Grey", "Arctic White", "Matte Black", "Taupe", "Slate",
    "Charcoal", "Silver", "Dove Grey", "Midnight Blue", "Cement"
